scriptsCode.callFunction:
// (服务端脚本组件)ServerScriptComp1.callFunction
var where = "1=1 ";
where += " and BILL_TYPE = '100601' ";
var plan = PO.getValue("plan","");
var userId = PO.getEnv("UserName","");
if(plan){
    where += " and (BILL_ID like '%'||" + "@{plan}@" + "||'%' OR PLAN_DESC like '%'||" + "@{plan}@" + "||'%') ";
}

var orgCode = PO.getValue("orgCode", "");

var isSuperAdmin = PO.getValue("isSuperAdmin", "");
if(!isSuperAdmin){
        where += " and exists( "
+"        select 1 from ( "
+"                select ORG_ID,ORG_PATH from SYS_ORG org "
+"                where exists ( "
+"                        select 1 from ( "
+"                        select SYS_ORG.ORG_PATH, BSUSSJ.* "
+"                        from SYS_ORG, BSUSSJ "
+"                        where "
+"                            SYS_ORG.ORG_ID = BSUSSJ.F_SJBH "
+"                            and BSUSSJ.F_ZGBH = '"+userId+"' "
+"                            and BSUSSJ.F_QXBH = 'SYS_ORG' "
+"                            and BSUSSJ.F_G2 = '1' "
+"                        union "
+"                        select SYS_ORG.ORG_PATH, BSUSSJ.* "
+"                        from SYS_ORG, BSUSSJ "
+"                        where "
+"                            SYS_ORG.ORG_ID = BSUSSJ.F_SJBH "
+"                            and BSUSSJ.F_QXBH = 'SYS_ORG' "
+"                            and BSUSSJ.F_G2 = '1' "
+"                            and exists (select 1 from bsuserrole b where BSUSSJ.F_ZGBH = b.F_ROLECODE and b.F_ZGBH = '"+userId+"' ) "
+"                        ) tmp where org.ORG_PATH like CONCAT(tmp.ORG_PATH, '%') "
+"                ) "
+"        ) gr where gr.ORG_ID =  EAM_EQ_SPECIAL_PLAN_HEAD.ORG_CODE ";
    where += " )";
}

if(orgCode != "" && orgCode != null){
    where += " and ( (select ORG_PATH from SYS_ORG where ORG_ID = EAM_EQ_SPECIAL_PLAN_HEAD.USE_ORG_CODE) like CONCAT((select ORG_PATH from SYS_ORG where ORG_ID = '"+orgCode+"' ), '%') or (select ORG_PATH from SYS_ORG where ORG_ID = EAM_EQ_SPECIAL_PLAN_HEAD.USE_DEPT_CODE) like CONCAT((select ORG_PATH from SYS_ORG where ORG_ID = '"+orgCode+"' ), '%') ) ";
}

PO.setParam("ENUMWHERE", where);
PO.setParam("EAM_EQ_SPECIAL_PLAN_HEAD_OrderBy"," BILL_ID DESC");

// (服务端脚本组件)ServerScriptComp2.callFunction
var isSuperAdmin = PO.getValue("isSuperAdmin","");
var BILL_ID = PO.getValue("BILL_ID","");
var STATUS = PO.getValue("STATUS","");
var orgCode = PO.getValue("orgCode","");
var userId = PO.getValue("userId","");
var where = " 1=1 ";
if(!isSuperAdmin){
    where += " and (exists(select 1 from VIEW_BSUSSJ_ORG org where org.f_g2='1' and org.f_zgbh='"+userId+"'  and (EAM_EQ_INV_PLAN_HEAD.ORG_CODE = org.ORG_ID))";
    where += " or CREATE_BY = '"+userId+"')";
}
if (BILL_ID) {
    where += " and (BILL_ID like concat('%"+BILL_ID+"','%') or IN_PLAN_DESC like concat('%"+BILL_ID+"','%'))";
}
if (STATUS) {
    where += " and STATUS = '" + STATUS + "'";
}
if (orgCode) {
    where += " and exists (select 1  from sys_org org2 where (org2.ORG_PATH like concat((select ORG_PATH  from sys_org outOrg where ORG_ID = '"+orgCode+"' limit 0,1), '.%') or ORG_PATH = (select ORG_PATH  from sys_org outOrg where ORG_ID = '"+orgCode+"' limit 0,1)) and (org2.ORG_ID =  EAM_EQ_INV_PLAN_HEAD.USE_ORG_CODE or org2.ORG_ID =  EAM_EQ_INV_PLAN_HEAD.ORG_CODE))";
}

PO.setParam("ENUMWHERE", where);
PO.setParam("EAM_EQ_INV_PLAN_HEAD_OrderBy"," BILL_ID DESC");
